library;

import 'package:apple_music_kit/apple_music_kit.dart';
import 'package:http/http.dart' as http;

/// Whether the example starts in mock mode. Mock mode requires no Apple
/// credentials and never touches Apple Music.
const useMockByDefault = bool.fromEnvironment('USE_MOCK', defaultValue: true);

/// Live-mode developer token provider.
///
/// SECURITY: developer tokens must be generated by your server (which holds
/// the Apple .p8 private key). This example fetches from a configurable
/// endpoint; NEVER embed a token or the private key in the client.
final class ExampleTokenProvider implements DeveloperTokenProvider {
  /// Override with --dart-define=TOKEN_ENDPOINT=https://your-server/token
  static const tokenEndpoint = String.fromEnvironment(
    'TOKEN_ENDPOINT',
    defaultValue: 'http://localhost:8787/developer-token',
  );

  @override
  Future<String> getToken() async {
    final response = await http.get(Uri.parse(tokenEndpoint)).timeout(
          const Duration(seconds: 10),
        );
    if (response.statusCode != 200) {
      throw Exception('Token endpoint returned ${response.statusCode}');
    }
    return response.body.trim();
  }
}
